  const prods = itemsOf("products"), svcs = itemsOf("services");
  const act = L.actionsOf(cfg), bookable = !!(cfg.booking.on && cfg.sections.booking), shopOn = !!(cfg.shop.on && cfg.sections.products);
  const today = L.todayLagos(Date.now()), annOn = cfg.announce.on && cfg.announce.text && (!cfg.announce.until || cfg.announce.until >= today);
  const hasItems = { products: prods.length, services: svcs.length, highlights: cfg.highlights.length, testimonials: cfg.testimonials.length, gallery: cfg.gallery.length, stats: cfg.stats.length, faq: cfg.faq.length,
    about: !!b.about, contact: !!(c.phone || c.whatsapp || c.email || c.address || c.hours || c.instagram || c.facebook || c.tiktok || c.x), booking: !!cfg.booking.on, enquiry: true,
    cta: !!((cfg.cta.title || cfg.cta.text) && (act.a !== "none" || act.first !== "none")), blk1: !!cfg.blocks[0], blk2: !!cfg.blocks[1], blk3: !!cfg.blocks[2] };
