  const heroFg = heroImg ? "#ffffff" : onColor(mix(c1, c2, 0.5));
  const pageBg = t.bgType === "gradient" ? `linear-gradient(170deg,${t.bg},${t.bgGradientTo})` : t.bg;
  const imgBgCss = t.bgType === "image" && t.bgImage ? `body{background-image:linear-gradient(rgba(0,0,0,${t.overlay / 100}),rgba(0,0,0,${t.overlay / 100})),url(${img(t.bgImage)});background-size:cover;background-attachment:fixed}` : "";

  /* ---------- actions ---------- */
  const actHref = k => ({ whatsapp: go("wa"), call: go("call"), shop: "#products", book: "#booking", enquire: "#enquiry" }[k] || "#");
  const actLabel = (k, custom) => custom || ({ whatsapp: tpl.id === "glow" ? "Book on WhatsApp" : tpl.id === "bistro" ? "Order on WhatsApp" : "Chat on WhatsApp", call: "Call us", shop: SHOP_LABEL[tpl.id] || "Shop now", book: BOOK_LABEL[tpl.id] || "Book now", enquire: ENQ_LABEL[tpl.id] || "Send an enquiry" }[k] || "");
  const actBtn = (k, cls, custom) => (k && k !== "none" ? `<a class="btn ${cls || ""}"${k === "whatsapp" || k === "call" ? ' rel="nofollow"' : ""} href="${actHref(k)}">${esc(actLabel(k, custom))}</a>` : "");

