    tile: (p, i, k) => `${open(p, k, "tile")}<div class="ph r45">${pic(p, 480, 600, "(min-width:760px) 33vw, 50vw")}${badge(p, k)}${more(p)}<div class="tl"><h3>${esc(p.name)}</h3>${price(p, k)}</div></div><div class="bd">${p.desc ? `<p class="d">${esc(p.desc)}</p>` : ""}<div class="ct">${k === "p" ? pCta(p, i) : sCta(p, i)}</div></div></article>`,
    menu: (p, i, k) => `${open(p, k, "menu")}${thumb(p, 96)}<div class="mb"><div class="mh"><h3${k === "p" && p.available === false ? ' class="x"' : ""}>${esc(p.name)}</h3><span class="dots"></span>${price(p, k)}</div>${p.desc ? `<p class="d">${esc(p.desc)}</p>` : ""}${badge(p, k)}<div class="ct">${k === "p" ? pCta(p, i, 1) : sCta(p, i, 1)}</div></div></article>`,
