    cta: () => { const a = cfg.cta.action === "auto" ? act.a : (act.has[cfg.cta.action] ? cfg.cta.action : act.a); const second = act.has.whatsapp && a !== "whatsapp" ? "whatsapp" : act.has.call && a !== "call" ? "call" : "none";
      return `<section id="cta" class="ctab"><div class="w ctin"><div><h2>${esc(cfg.cta.title || "Ready when you are")}</h2>${cfg.cta.text ? `<p>${esc(cfg.cta.text)}</p>` : ""}</div><div class="hb">${actBtn(a === "none" ? act.first : a, "", cfg.cta.label)}${actBtn(second, "ghost")}</div></div></section>`; },
