  const heroHtml = `<section class="hero h-${heroKind}${heroImg ? " has-img" : ""}"><div class="hbg">${heroMedia}</div><div class="w hin"><div class="ht">${b.headline ? `<p class="kick">${esc(name)}</p>` : ""}<h1>${esc(headline)}</h1>${b.tagline ? `<p class="${b.headline ? "lead" : "kick"}">${esc(b.tagline)}</p>` : ""}${hbtns ? `<div class="hb">${hbtns}</div>` : ""}${facts ? `<div class="facts-line">${facts}</div>` : ""}</div>${heroKind === "split" ? `<div class="hv">${heroImg ? `<img width="900" height="900" fetchpriority="high" src="${img(heroImg)}/s" srcset="${ss(heroImg)}" sizes="(min-width:860px) 45vw, 100vw" alt="">` : `<div class="hart"></div>`}</div>` : ""}</div></section>`;

